// Main entry point for the 3D RTS game
const THREE = require('three');
const gsap = require('gsap');
const io = require('socket.io-client');

class GameEngine {
  constructor() {
    this.initializeGame();
  }

  initializeGame() {
    this.canvas = document.getElementById('gameCanvas');
    this.scene = new THREE.Scene();
    this.camera = new THREE.Camera();
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true });

    // Initialize game systems
    this.gameSystems = {
      graphics: new GraphicsSystem(this.scene, this.camera),
      input: new InputSystem(),
      gameLogic: new GameLogicSystem(),
      audio: new AudioSystem(),
      ui: new UISystem()
    };

    // Initialize game state
    this.gameState = new GameState();

    // Start game loop
    this.startGameLoop();
  }

  startGameLoop() {
    const animate = () => {
      requestAnimationFrame(animate);

      // Update game systems
      this.gameSystems.graphics.update();
      this.gameSystems.input.update();
      this.gameLogic.update();
      this.gameSystems.ui.update();

      // Render frame
      this.gameSystems.graphics.render();
    };

    animate();
  }
}

// Global game instance
window.game = new GameEngine();

class GameState {
  constructor() {
    // Game mode
    this.gameMode = 'MENU'; // MENU, PLAYING, PAUSED, GAME_OVER
    this.multiplayerMode = 'OFFLINE'; // OFFLINE, LAN, ONLINE

    // Player data
    this.players = [];
    this.currentPlayer = null;
    this.selectedPlayer = 0; // Index of currently selected player

    // Game world
    this.gameWorld = {
      map: {
        width: 1000,
        height: 1000,
        terrain: [],
        resources: [],
        structures: [],
        units: []
      },
      time: {
        dayNightCycle: 0,
        weather: 'clear',
        timeOfDay: 'morning'
      },
      economy: {
        wood: 500,
        gold: 500,
        magic: 500,
        food: 100,
        population: 10
      }
    };

    // Game settings
    this.settings = {
      soundVolume: 1.0,
      musicVolume: 1.0,
      cameraMode: 'Strategic', // Strategic, Base, Free
      unitIcons: true,
      resourceIndicators: true,
      pathfinding: true,
      autoSelect: false
    };

    // Tech tree data
    this.techTree = {
      human: [],
      nightElf: [],
      orc: []
    };

    // Save game data
    this.saveData = {
      lastSave: null,
      autoSaveInterval: 300000, // 5 minutes
      checkpoints: []
    };

    // Game statistics
    this.statistics = {
      gamesPlayed: 0,
      wins: 0,
      losses: 0,
      totalPlayTime: 0,
      unitsKilled: { human: 0, nightElf: 0, orc: 0 },
      resourcesCollected: { wood: 0, gold: 0, magic: 0, food: 0 }
    };
  }

  // Player management methods
  addPlayer(name, race, color) {
    const player = {
      id: this.players.length,
      name,
      race,
      color,
      civilization: {
        health: 100,
        foodProduction: 0,
        woodProduction: 0,
        goldProduction: 0,
        magicProduction: 0,
        buildings: [],
        units: [],
        technologies: []
      },
      startLocation: {
        x: Math.random() * 800 + 100,
        y: Math.random() * 800 + 100,
        z: 0
      },
      resources: {
        wood: 500,
        gold: 500,
        magic: 500,
        food: 100
      }
    };

    this.players.push(player);
    if (this.players.length === 1) {
      this.currentPlayer = player;
    }

    return player;
  }

  selectPlayer(index) {
    if (index >= 0 && index < this.players.length) {
      this.selectedPlayer = index;
      this.currentPlayer = this.players[index];
      return this.currentPlayer;
    }
    return null;
  }

  // Economy management methods
  addResources(type, amount) {
    this.gameWorld.economy[type] += amount;
    this.gameState.statistics.resourcesCollected[type] += amount;
    this.gameSystems.ui.updateResourceDisplay();
  }

  consumeResources(types) {
    for (const type of Object.keys(types)) {
      this.gameWorld.economy[type] -= types[type];
    }
    this.gameSystems.ui.updateResourceDisplay();
  }

  // Game state methods
  saveGame() {
    this.gameState.saveData.lastSave = new Date();
    // TODO: Implement save to file
  }

  loadGame() {
    // TODO: Implement load from file
    // TODO: Restore game state
  }

  resetGame() {
    this.players = [];
    this.currentPlayer = null;
    this.selectedPlayer = 0;
    this.gameMode = 'MENU';
    this.statistics = {
      gamesPlayed: this.statistics.gamesPlayed + 1,
      wins: this.statistics.wins + (this.currentPlayer?.civilization.health > 0 ? 1 : 0),
      losses: this.statistics.losses + (this.currentPlayer?.civilization.health <= 0 ? 1 : 0),
      totalPlayTime: 0,
      unitsKilled: { human: 0, nightElf: 0, orc: 0 },
      resourcesCollected: { wood: 0, gold: 0, magic: 0, food: 0 }
    };
    this.gameSystems.ui.updateStatisticsDisplay();
  }
}

module.exports = GameState;

class GraphicsSystem {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.renderer = null;
    this.lights = [];
    this.models = new Map();
    this.textures = new Map();
    this.particleSystems = [];

    // Initialize graphics
    this.initializeGraphics();
  }

  initializeGraphics() {
    // Setup renderer
    this.renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: 'high-performance'
    });

    // Configure renderer
    this.renderer.setPixelRatio(window.devicePixelRatio);
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;

    // Setup scene
    this.scene.background = new THREE.Color(0x1a1a2e);
    this.scene.fog = new THREE.FogExp2(0x1a1a2e, 0.02);

    // Setup lighting
    this.setupLighting();

    // Setup camera
    this.setupCamera();

    // Initialize models
    this.initializeModels();
  }

  setupLighting() {
    // Ambient light
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
    this.scene.add(ambientLight);

    // Directional light (sun)
    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.0);
    directionalLight.position.set(100, 100, 50);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    this.scene.add(directionalLight);
    this.lights.push(directionalLight);

    // Point lights for special effects
    const pointLight1 = new THREE.PointLight(0xff6b6b, 0.5, 100);
    pointLight1.position.set(50, 30, 20);
    this.scene.add(pointLight1);
    this.lights.push(pointLight1);

    const pointLight2 = new THREE.PointLight(0x4ecdc4, 0.5, 100);
    pointLight2.position.set(-50, 30, 20);
    this.scene.add(pointLight2);
    this.lights.push(pointLight2);
  }

  setupCamera() {
    this.camera.position.set(0, 50, 100);
    this.camera.lookAt(0, 0, 0);
  }

  initializeModels() {
    // Create unit models
    this.createHumanUnits();
    this.createNightElfUnits();
    this.createOrcUnits();

    // Create structure models
    this.createStructures();

    // Create environment models
    this.createEnvironment();
  }

  createHumanUnits() {
    // Knight model
    const knightGeometry = new THREE.BoxGeometry(0.8, 2.0, 0.8);
    const knightMaterial = new THREE.MeshLambertMaterial({ color: 0x4a90e2 });
    const knight = new THREE.Mesh(knightGeometry, knightMaterial);
    knight.castShadow = true;
    knight.receiveShadow = true;
    this.models.set('knight', knight);

    // Archer model
    const archerGeometry = new THREE.BoxGeometry(0.6, 1.8, 0.6);
    const archerMaterial = new THREE.MeshLambertMaterial({ color: 0x7fdb8d });
    const archer = new THREE.Mesh(archerGeometry, archerMaterial);
    archer.castShadow = true;
    archer.receiveShadow = true;
    this.models.set('archer', archer);

    // Wizard model
    const wizardGeometry = new THREE.BoxGeometry(0.7, 2.2, 0.7);
    const wizardMaterial = new THREE.MeshLambertMaterial({ color: 0xd65381 });
    const wizard = new THREE.Mesh(wizardGeometry, wizardMaterial);
    wizard.castShadow = true;
    wizard.receiveShadow = true;
    this.models.set('wizard', wizard);
  }

  createNightElfUnits() {
    // Ranger model
    const rangerGeometry = new THREE.BoxGeometry(0.7, 2.0, 0.7);
    const rangerMaterial = new THREE.MeshLambertMaterial({ color: 0x95e77e });
    const ranger = new THREE.Mesh(rangerGeometry, rangerMaterial);
    ranger.castShadow = true;
    ranger.receiveShadow = true;
    this.models.set('ranger', ranger);

    // Druid model
    const druidGeometry = new THREE.BoxGeometry(0.8, 2.2, 0.8);
    const druidMaterial = new THREE.MeshLambertMaterial({ color: 0x56cfe1 });
    const druid = new THREE.Mesh(druidGeometry, druidMaterial);
    druid.castShadow = true;
    druid.receiveShadow = true;
    this.models.set('druid', druid);

    // Phoenix model
    const phoenixGeometry = new THREE.BoxGeometry(1.2, 1.5, 1.2);
    const phoenixMaterial = new THREE.MeshLambertMaterial({ color: 0xff6b35 });
    const phoenix = new THREE.Mesh(phoenixGeometry, phoenixMaterial);
    phoenix.castShadow = true;
    phoenix.receiveShadow = true;
    this.models.set('phoenix', phoenix);
  }

  createOrcUnits() {
    // Grunt model
    const gruntGeometry = new THREE.BoxGeometry(0.9, 2.0, 0.9);
    const gruntMaterial = new THREE.MeshLambertMaterial({ color: 0xe74c3c });
    const grunt = new THREE.Mesh(gruntGeometry, gruntMaterial);
    grunt.castShadow = true;
    grunt.receiveShadow = true;
    this.models.set('grunt', grunt);

    // Shaman model
    const shamanGeometry = new THREE.BoxGeometry(0.8, 2.1, 0.8);
    const shamanMaterial = new THREE.MeshLambertMaterial({ color: 0x34495e });
    const shaman = new THREE.Mesh(shamanGeometry, shamanMaterial);
    shaman.castShadow = true;
    shaman.receiveShadow = true;
    this.models.set('shaman', shaman);

    // Warlock model
    const warlockGeometry = new THREE.BoxGeometry(0.7, 2.3, 0.7);
    const warlockMaterial = new THREE.MeshLambertMaterial({ color: 0x8e44ad });
    const warlock = new THREE.Mesh(warlockGeometry, warlockMaterial);
    warlock.castShadow = true;
    warlock.receiveShadow = true;
    this.models.set('warlock', warlock);
  }

  createStructures() {
    // Human structures
    const humanBarracksGeometry = new THREE.BoxGeometry(4, 3, 4);
    const humanBarracksMaterial = new THREE.MeshLambertMaterial({ color: 0x3a5885 });
    const humanBarracks = new THREE.Mesh(humanBarracksGeometry, humanBarracksMaterial);
    humanBarracks.castShadow = true;
    humanBarracks.receiveShadow = true;
    this.models.set('humanBarracks', humanBarracks);

    const humanArcheryRangeGeometry = new THREE.BoxGeometry(5, 3, 6);
    const humanArcheryRangeMaterial = new THREE.MeshLambertMaterial({ color: 0x4a7c59 });
    const humanArcheryRange = new THREE.Mesh(humanArcheryRangeGeometry, humanArcheryRangeMaterial);
    humanArcheryRange.castShadow = true;
    humanArcheryRange.receiveShadow = true;
    this.models.set('humanArcheryRange', humanArcheryRange);

    // Night Elf structures
    const elfLodgeGeometry = new THREE.BoxGeometry(4, 3, 4);
    const elfLodgeMaterial = new THREE.MeshLambertMaterial({ color: 0x2e7d32 });
    const elfLodge = new THREE.Mesh(elfLodgeGeometry, elfLodgeMaterial);
    elfLodge.castShadow = true;
    elfLodge.receiveShadow = true;
    this.models.set('elfLodge', elfLodge);

    // Orc structures
    const orcBarracksGeometry = new THREE.BoxGeometry(4, 3, 4);
    const orcBarracksMaterial = new THREE.MeshLambertMaterial({ color: 0x8b0000 });
    const orcBarracks = new THREE.Mesh(orcBarracksGeometry, orcBarracksMaterial);
    orcBarracks.castShadow = true;
    orcBarracks.receiveShadow = true;
    this.models.set('orcBarracks', orcBarracks);
  }

  createEnvironment() {
    // Tree geometry
    const treeGeometry = new THREE.ConeGeometry(0.5, 3, 4);
    const treeMaterial = new THREE.MeshLambertMaterial({ color: 0x2e7d32 });
    const tree = new THREE.Mesh(treeGeometry, treeMaterial);
    tree.castShadow = true;
    this.models.set('tree', tree);

    // Rock geometry
    const rockGeometry = new THREE.IcosahedronGeometry(1, 1);
    const rockMaterial = new THREE.MeshLambertMaterial({ color: 0x546a7b });
    const rock = new THREE.Mesh(rockGeometry, rockMaterial);
    rock.castShadow = true;
    this.models.set('rock', rock);
  }

  update() {
    // Update lights
    this.updateLighting();

    // Update particle systems
    for (const particleSystem of this.particleSystems) {
      particleSystem.update();
    }
  }

  updateLighting() {
    // Update sun position based on time of day
    const sunLight = this.lights[1]; // Directional light
    if (sunLight) {
      const timeOfDay = window.game.gameState.gameWorld.time.timeOfDay;
      if (timeOfDay === 'morning') {
        sunLight.position.set(100, 80, 50);
        sunLight.intensity = 0.8;
      } else if (timeOfDay === 'afternoon') {
        sunLight.position.set(50, 100, 0);
        sunLight.intensity = 1.0;
      } else if (timeOfDay === 'evening') {
        sunLight.position.set(-50, 60, -50);
        sunLight.intensity = 0.6;
      } else if (timeOfDay === 'night') {
        sunLight.position.set(-20, 20, -20);
        sunLight.intensity = 0.3;

        // Add night effects
        this.scene.fog.color.setHex(0x0a0a2e);
        this.scene.background = new THREE.Color(0x0a0a2e);
      }
    }
  }

  render() {
    this.renderer.render(this.scene, this.camera);
  }

  createParticleSystem(type, position, options) {
    const particleSystem = new ParticleSystem(type, position, options);
    this.particleSystems.push(particleSystem);
    return particleSystem;
  }

  dispose() {
    // Clean up resources
    this.renderer.dispose();

    for (const model of this.models.values()) {
      if (model.geometry) model.geometry.dispose();
      if (model.material) {
        if (Array.isArray(model.material)) {
          for (const material of model.material) {
            material.dispose();
          }
        } else {
          model.material.dispose();
        }
      }
    }

    for (const texture of this.textures.values()) {
      texture.dispose();
    }
  }
}

class ParticleSystem {
  constructor(type, position, options = {}) {
    this.type = type;
    this.position = position.clone();
    this.options = options;
    this.particles = [];
    this.lifetime = 0;
    this.duration = options.duration || 5000;
    this.particleCount = options.particleCount || 100;

    this.initializeParticles();
  }

  initializeParticles() {
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(this.particleCount * 3);
    const colors = new Float32Array(this.particleCount * 3);
    const sizes = new Float32Array(this.particleCount);
    const lifespans = new Float32Array(this.particleCount);

    for (let i = 0; i < this.particleCount; i++) {
      const i3 = i * 3;
      positions[i3] = this.position.x;
      positions[i3 + 1] = this.position.y;
      positions[i3 + 2] = this.position.z;

      colors[i3] = 1.0;
      colors[i3 + 1] = 1.0;
      colors[i3 + 2] = 1.0;

      sizes[i] = Math.random() * 0.5 + 0.5;
      lifespans[i] = Math.random() * this.duration;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));
    geometry.setAttribute('lifespan', new THREE.BufferAttribute(lifespans, 1));

    const material = new THREE.ShaderMaterial({
      uniforms: {
        time: { value: 0 },
        center: { value: new THREE.Vector3(0, 0, 0) }
      },
      vertexShader: this.getVertexShader(),
      fragmentShader: this.getFragmentShader(),
      transparent: true,
      blending: THREE.AdditiveBlending
    });

    this.mesh = new THREE.Points(geometry, material);
    this.mesh.position.copy(this.position);

    return this.mesh;
  }

  update() {
    this.lifetime += 16; // Assuming 60fps

    const geometry = this.mesh.geometry;
    const positions = geometry.getAttribute('position');
    const colors = geometry.getAttribute('color');
    const sizes = geometry.getAttribute('size');
    const lifespans = geometry.getAttribute('lifespan');

    for (let i = 0; i < this.particleCount; i++) {
      const i3 = i * 3;

      // Update particle position based on type
      if (this.type === 'explosion') {
        const age = this.lifespan % this.duration;
        const factor = age / this.duration;

        positions[i3] = this.position.x + (Math.random() - 0.5) * factor * 10;
        positions[i3 + 1] = this.position.y + factor * 5 + Math.sin(factor * Math.PI * 2) * 2;
        positions[i3 + 2] = this.position.z + (Math.random() - 0.5) * factor * 10;
      }

      // Update colors based on age
      const age = this.lifetime % this.duration;
      const lifeRatio = 1.0 - (age / this.duration);

      colors[i3] = lifeRatio * 1.0;
      colors[i3 + 1] = lifeRatio * 1.0;
      colors[i3 + 2] = lifeRatio * 1.0;

      // Update sizes
      sizes[i] = (Math.random() * 0.5 + 0.5) * lifeRatio;
    }

    positions.needsUpdate = true;
    colors.needsUpdate = true;
    sizes.needsUpdate = true;

    // Update shader uniforms
    this.mesh.material.uniforms.time.value = this.lifetime;

    // Remove particle system if expired
    if (this.lifetime > this.duration && window.game) {
      window.game.gameSystems.graphics.particleSystems = window.game.gameSystems.graphics.particleSystems.filter(
        system => system !== this
      );
    }
  }

  getVertexShader() {
    return `
      attribute float size;
      attribute float lifespan;
      varying vec3 vColor;

      uniform float time;
      uniform vec3 center;

      void main() {
        vColor = color;
        vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
        gl_Position = projectionMatrix * mvPosition;
        gl_PointSize = size * (300.0 / length(mvPosition.xyz));
      }
    `;
  }

  getFragmentShader() {
    return `
      varying vec3 vColor;
      uniform float time;

      void main() {
        float alpha = 1.0 - smoothstep(0.0, 1.0, length(gl_PointCoord - vec2(0.5)));
        gl_FragColor = vec4(vColor, alpha * 0.8);
      }
    `;
  }
}

module.exports = { GraphicsSystem, ParticleSystem };

class InputSystem {
  constructor() {
    this.keys = {};
    this.mouse = {
      x: 0,
      y: 0,
      buttons: { left: false, right: false, middle: false },
      wheel: 0
    };
    this.touches = [];
    this.cameraControl = {
      rotate: { x: 0, y: 0 },
      zoom: 1.0,
      pan: { x: 0, y: 0 }
    };

    this.initializeInput();
  }

  initializeInput() {
    // Keyboard input
    window.addEventListener('keydown', (event) => {
      this.keys[event.code] = true;

      // Handle special keys
      switch (event.code) {
        case 'Escape':
          if (window.game) window.game.gameSystems.input.handleEscape();
          break;
        case 'Tab':
          event.preventDefault();
          if (window.game) window.game.gameSystems.input.handleTab();
          break;
        case 'ControlLeft':
        case 'ControlRight':
          this.keys['CONTROL'] = true;
          break;
        case 'ShiftLeft':
        case 'ShiftRight':
          this.keys['SHIFT'] = true;
          break;
      }
    });

    window.addEventListener('keyup', (event) => {
      this.keys[event.code] = false;

      // Handle special keys
      switch (event.code) {
        case 'ControlLeft':
        case 'ControlRight':
          this.keys['CONTROL'] = false;
          break;
        case 'ShiftLeft':
        case 'ShiftRight':
          this.keys['SHIFT'] = false;
          break;
      }
    });

    // Mouse input
    window.addEventListener('mousemove', (event) => {
      this.mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
      this.mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

      if (window.game) {
        window.game.gameSystems.input.handleMouseMove(event);
      }
    });

    window.addEventListener('mousedown', (event) => {
      this.mouse.buttons[`${['left', 'middle', 'right'][event.button]}`] = true;

      if (window.game) {
        window.game.gameSystems.input.handleMouseDown(event);
      }
    });

    window.addEventListener('mouseup', (event) => {
      this.mouse.buttons[`${['left', 'middle', 'right'][event.button]}`] = false;

      if (window.game) {
        window.game.gameSystems.input.handleMouseUp(event);
      }
    });

    window.addEventListener('wheel', (event) => {
      this.mouse.wheel += event.deltaY * 0.001;

      if (window.game) {
        window.game.gameSystems.input.handleMouseWheel(event);
      }
    });

    // Touch input for mobile
    window.addEventListener('touchstart', (event) => {
      event.preventDefault();
      for (let i = 0; i < event.touches.length; i++) {
        this.touches.push({
          id: event.touches[i].identifier,
          x: event.touches[i].clientX,
          y: event.touches[i].clientY
        });
      }

      if (window.game) {
        window.game.gameSystems.input.handleTouchStart(event);
      }
    });

    window.addEventListener('touchmove', (event) => {
      event.preventDefault();
      for (let i = 0; i < event.touches.length; i++) {
        const touch = this.touches.find(t => t.id === event.touches[i].identifier);
        if (touch) {
          touch.x = event.touches[i].clientX;
          touch.y = event.touches[i].clientY;
        }
      }

      if (window.game) {
        window.game.gameSystems.input.handleTouchMove(event);
      }
    });

    window.addEventListener('touchend', (event) => {
      event.preventDefault();
      this.touches = this.touches.filter(touch => !event.touches.find(t => t.id === touch.id));

      if (window.game) {
        window.game.gameSystems.input.handleTouchEnd(event);
      }
    });

    // Window resize
    window.addEventListener('resize', () => {
      if (window.game && window.game.gameSystems.graphics.renderer) {
        window.game.gameSystems.graphics.renderer.setSize(window.innerWidth, window.innerHeight);
        window.game.gameSystems.input.handleResize();
      }
    });

    // Gamepad input (for keyboard-less controls)
    window.addEventListener('gamepadconnected', (event) => {
      console.log('Gamepad connected:', event.gamepad);
    });

    window.addEventListener('gamepaddisconnected', (event) => {
      console.log('Gamepad disconnected:', event.gamepad);
    });
  }

  handleMouseMove(event) {
    // Calculate delta movement
    const deltaX = event.movementX || 0;
    const deltaY = event.movementY || 0;

    // Update camera controls based on camera mode
    const cameraMode = window.game ? window.game.gameState.settings.cameraMode : 'Strategic';

    switch (cameraMode) {
      case 'Strategic':
        // Rotate camera around the scene
        this.cameraControl.rotate.y -= deltaX * 0.01;
        this.cameraControl.rotate.x -= deltaY * 0.01;
        break;
      case 'Base':
        // Pan camera
        this.cameraControl.pan.x += deltaX * 0.005;
        this.cameraControl.pan.y += deltaY * 0.005;
        break;
      case 'Free':
        // Free camera movement
        // TODO: Implement free camera movement
        break;
    }

    // Apply camera transformations
    this.applyCameraTransformations();
  }

  handleMouseDown(event) {
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    // Calculate mouse position in normalized device coordinates
    mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
    mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

    // Update the picking ray with the camera and mouse position
    raycaster.setFromCamera(mouse, window.game.gameSystems.graphics.camera);

    // Calculate objects intersecting the picking ray
    const intersects = raycaster.intersectObjects(window.game.gameState.gameWorld.map.structures);

    if (intersects.length > 0) {
      // Object was clicked
      const object = intersects[0].object;
      const structure = window.game.gameState.gameWorld.map.structures.find(s => s.mesh === object);

      if (structure) {
        // Handle structure click
        window.game.gameSystems.ui.selectStructure(structure);
      }
    } else {
      // Empty space clicked - deselect units
      window.game.gameSystems.ui.deselectAll();
    }
  }

  handleMouseUp(event) {
    // Handle mouse button release
  }

  handleMouseWheel(event) {
    // Zoom camera
    this.cameraControl.zoom += event.deltaY * 0.001;
    this.cameraControl.zoom = Math.max(0.1, Math.min(5.0, this.cameraControl.zoom));
    this.applyCameraTransformations();
  }

  handleTouchStart(event) {
    // Handle touch input for mobile devices
    // TODO: Implement mobile touch controls
  }

  handleTouchMove(event) {
    // Handle touch movement for mobile devices
    // TODO: Implement mobile touch controls
  }

  handleTouchEnd(event) {
    // Handle touch end for mobile devices
    // TODO: Implement mobile touch controls
  }

  handleEscape() {
    // Toggle pause menu
    if (window.game) {
      if (window.game.gameState.gameMode === 'PLAYING') {
        window.game.gameState.gameMode = 'PAUSED';
        window.game.gameSystems.ui.showPauseMenu();
      } else if (window.game.gameState.gameMode === 'PAUSED') {
        window.game.gameState.gameMode = 'PLAYING';
        window.game.gameSystems.ui.hidePauseMenu();
      }
    }
  }

  handleTab() {
    // Cycle through selected units
    if (window.game) {
      window.game.gameSystems.ui.cycleUnitSelection();
    }
  }

  handleResize() {
    if (window.game && window.game.gameSystems.graphics.renderer) {
      const canvas = window.game.gameSystems.graphics.renderer.domElement;
      const width = window.innerWidth;
      const height = window.innerHeight;

      canvas.style.width = width + 'px';
      canvas.style.height = height + 'px';

      window.game.gameSystems.graphics.renderer.setSize(width, height);
      this.applyCameraTransformations();
    }
  }

  applyCameraTransformations() {
    if (!window.game) return;

    const camera = window.game.gameSystems.graphics.camera;
    const cameraMode = window.game.gameState.settings.cameraMode;

    // Reset camera position
    camera.position.set(0, 50, 100);
    camera.lookAt(0, 0, 0);

    switch (cameraMode) {
      case 'Strategic':
        // Strategic view: rotate around the center
        camera.position.x = 100 * Math.cos(this.cameraControl.rotate.y);
        camera.position.z = 100 * Math.sin(this.cameraControl.rotate.y);
        camera.position.y = 50 + 30 * Math.sin(this.cameraControl.rotate.x);
        camera.lookAt(0, 0, 0);
        break;
      case 'Base':
        // Base view: follow the current player's selected unit/base
        const player = window.game.gameState.currentPlayer;
        if (player && player.civilization.buildings.length > 0) {
          const mainBuilding = player.civilization.buildings[0];
          camera.position.copy(mainBuilding.position.clone().add(new THREE.Vector3(0, 10, 10)));
          camera.lookAt(mainBuilding.position);
        }
        break;
      case 'Free':
        // Free camera: allow free movement
        // TODO: Implement free camera movement
        break;
    }

    // Apply zoom
    camera.position.multiplyScalar(this.cameraControl.zoom);

    // Apply pan offset
    camera.position.x += this.cameraControl.pan.x;
    camera.position.z += this.cameraControl.pan.y;
  }

  update() {
    // Check for keyboard input
    this.checkKeyboardInput();

    // Update touch positions
    this.updateTouchPositions();

    // Update camera controls
    this.applyCameraTransformations();
  }

  checkKeyboardInput() {
    // Handle camera movement
    if (this.keys['KeyW'] || this.keys['ArrowUp']) {
      // Move camera forward
      this.cameraControl.pan.y -= 0.01;
    }
    if (this.keys['KeyS'] || this.keys['ArrowDown']) {
      // Move camera backward
      this.cameraControl.pan.y += 0.01;
    }
    if (this.keys['KeyA'] || this.keys['ArrowLeft']) {
      // Move camera left
      this.cameraControl.pan.x -= 0.01;
    }
    if (this.keys['KeyD'] || this.keys['ArrowRight']) {
      // Move camera right
      this.cameraControl.pan.x += 0.01;
    }
    if (this.keys['KeyE']) {
      // Raise camera
      this.cameraControl.pan.y += 0.01;
    }
    if (this.keys['KeyQ']) {
      // Lower camera
      this.cameraControl.pan.y -= 0.01;
    }

    // Handle unit actions
    if (window.game) {
      if (this.keys['KeyR']) {
        // Build command
        window.game.gameSystems.input.handleBuildCommand();
      }
      if (this.keys['KeyF']) {
        // Attack command
        window.game.gameSystems.input.handleAttackCommand();
      }
      if (this.keys['KeyG']) {
        // Gather command
        window.game.gameSystems.input.handleGatherCommand();
      }
      if (this.keys['KeyT']) {
        // Train unit command
        window.game.gameSystems.input.handleTrainCommand();
      }
    }
  }

  updateTouchPositions() {
    // Update touch positions for mobile
    // TODO: Implement mobile touch controls
  }

  getMouseWorldPosition() {
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    // Calculate mouse position in normalized device coordinates
    mouse.x = (this.mouse.x / 2) * window.innerWidth;
    mouse.y = -(this.mouse.y / 2) * window.innerHeight;

    // Update the picking ray with the camera and mouse position
    raycaster.setFromCamera(mouse, window.game.gameSystems.graphics.camera);

    // Calculate objects intersecting the picking ray
    const intersects = raycaster.intersectObjects(window.game.gameState.gameWorld.map.structures);

    if (intersects.length > 0) {
      return intersects[0].point;
    }

    return null;
  }
}

module.exports = InputSystem;

class AudioSystem {
  constructor() {
    this.audioContext = null;
    this.gainNode = null;
    this.masterGain = null;
    this.soundBuffers = new Map();
    this.musicBuffers = new Map();
    this.activeSources = [];
    this.listeners = [];

    this.initializeAudio();
  }

  initializeAudio() {
    try {
      // Initialize Web Audio API
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
      this.masterGain = this.audioContext.createGain();
      this.masterGain.connect(this.audioContext.destination);

      this.masterGain.gain.setValueAtTime(1.0, this.audioContext.currentTime);

      // Load default sounds
      this.loadDefaultSounds();
      this.loadDefaultMusic();
    } catch (error) {
      console.warn('Web Audio API not supported, falling back to HTML5 Audio:', error);
      this.useHtml5Audio = true;
      this.initializeHtml5Audio();
    }
  }

  loadDefaultSounds() {
    const soundFiles = {
      'buttonClick': '/sounds/button-click.wav',
      'buildComplete': '/sounds/build-complete.wav',
      'unitCreated': '/sounds/unit-created.wav',
      'unitDie': '/sounds/unit-die.wav',
      'explosion': '/sounds/explosion.wav',
      'resourceGather': '/sounds/resource-gather.wav',
      'buyUnit': '/sounds/buy-unit.wav',
      'technologyResearch': '/sounds/technology-research.wav',
      'alert': '/sounds/alert.wav'
    };

    for (const [name, path] of Object.entries(soundFiles)) {
      this.loadSound(name, path);
    }
  }

  loadDefaultMusic() {
    const musicFiles = {
      'menu': '/music/menu-music.mp3',
      'overworld': '/music/overworld-music.mp3',
      'battle': '/music/battle-music.mp3',
      'victory': '/music/victory-music.mp3'
    };

    for (const [name, path] of Object.entries(musicFiles)) {
      this.loadMusic(name, path);
    }
  }

  loadSound(name, url) {
    const request = new XMLHttpRequest();
    request.open('GET', url, true);
    request.responseType = 'arraybuffer';

    request.onload = () => {
      this.audioContext.decodeAudioData(
        request.response,
        (buffer) => {
          this.soundBuffers.set(name, buffer);
          this.notifyListeners('soundLoaded', name);
        },
        (error) => {
          console.error(`Error decoding sound ${name}:`, error);
        }
      );
    };

    request.onerror = () => {
      console.error(`Error loading sound ${name}:`, request.statusText);
    };

    request.send();
  }

  loadMusic(name, url) {
    const audio = new Audio();
    audio.loop = true;
    audio.preload = 'auto';

    audio.addEventListener('canplaythrough', () => {
      this.musicBuffers.set(name, audio);
      this.notifyListeners('musicLoaded', name);
    });

    audio.addEventListener('error', (error) => {
      console.error(`Error loading music ${name}:`, error);
    });

    audio.src = url;
  }

  playSound(name, options = {}) {
    if (!this.audioContext || this.soundBuffers.size === 0) {
      return;
    }

    const buffer = this.soundBuffers.get(name);
    if (!buffer) {
      console.warn(`Sound not found: ${name}`);
      return;
    }

    const source = this.audioContext.createBufferSource();
    const gainNode = this.audioContext.createGain();

    source.buffer = buffer;
    source.connect(gainNode);
    gainNode.connect(this.masterGain);

    // Configure gain
    gainNode.gain.setValueAtTime(1.0, this.audioContext.currentTime);
    if (options.volume) {
      gainNode.gain.setValueAtTime(options.volume, this.audioContext.currentTime);
    }

    // Configure pan
    if (options.pan) {
      const panner = this.audioContext.createStereoPanner();
      panner.pan.setValueAtTime(options.pan, this.audioContext.currentTime);
      gainNode.connect(panner);
      panner.connect(this.masterGain);
    }

    // Play sound
    source.start(0);

    // Track source for cleanup
    this.activeSources.push({
      source,
      gainNode,
      panner: options.pan ? panner : null,
      startTime: this.audioContext.currentTime
    });

    // Remove from active sources when done
    source.addEventListener('ended', () => {
      this.activeSources = this.activeSources.filter(active => active.source !== source);
    });
  }

  playMusic(name, options = {}) {
    if (this.useHtml5Audio) {
      this.playHtml5Music(name, options);
      return;
    }

    const audio = this.musicBuffers.get(name);
    if (!audio) {
      console.warn(`Music not found: ${name}`);
      return;
    }

    // Stop currently playing music
    this.stopAllMusic();

    // Configure volume
    audio.volume = options.volume || 1.0;

    // Play music
    audio.play();
  }

  stopAllMusic() {
    for (const music of this.musicBuffers.values()) {
      if (this.useHtml5Audio) {
        music.pause();
        music.currentTime = 0;
      } else {
        // For Web Audio API, we need to stop all sources
        for (const source of this.activeSources) {
          source.source.stop();
        }
      }
    }
  }

  setMusicVolume(volume) {
    if (this.masterGain) {
      this.masterGain.gain.setValueAtTime(volume, this.audioContext.currentTime);
    }

    if (this.useHtml5Audio) {
      for (const music of this.musicBuffers.values()) {
        music.volume = volume;
      }
    }
  }

  setSoundVolume(volume) {
    if (this.masterGain) {
      this.masterGain.gain.setValueAtTime(volume, this.audioContext.currentTime);
    }
  }

  pauseAllAudio() {
    if (this.useHtml5Audio) {
      for (const music of this.musicBuffers.values()) {
        music.pause();
      }
    } else {
      for (const source of this.activeSources) {
        source.source.stop();
      }
    }
  }

  resumeAllAudio() {
    if (this.useHtml5Audio) {
      for (const music of this.musicBuffers.values()) {
        if (music.paused) {
          music.play();
        }
      }
    }
  }

  initializeHtml5Audio() {
    // Fallback for browsers without Web Audio API
    this.html5Audio = {};
    this.html5Music = {};

    for (const [name, buffer] of this.soundBuffers.entries()) {
      const audio = new Audio();
      audio.src = URL.createObjectURL(buffer); // This is simplified
      this.html5Audio[name] = audio;
    }

    for (const [name, audio] of this.musicBuffers.entries()) {
      this.html5Music[name] = audio;
    }
  }

  playHtml5Sound(name, options = {}) {
    const audio = this.html5Audio[name];
    if (!audio) {
      return;
    }

    audio.volume = options.volume || 1.0;
    audio.currentTime = 0;
    audio.play();
  }

  playHtml5Music(name, options = {}) {
    // Stop currently playing music
    for (const music of Object.values(this.html5Music)) {
      music.pause();
      music.currentTime = 0;
    }

    const audio = this.html5Music[name];
    if (!audio) {
      return;
    }

    audio.volume = options.volume || 1.0;
    audio.play();
  }

  addEventListener(type, callback) {
    this.listeners.push({ type, callback });
  }

  removeEventListener(type, callback) {
    this.listeners = this.listeners.filter(
      listener => listener.type !== type || listener.callback !== callback
    );
  }

  notifyListeners(type, ...args) {
    for (const listener of this.listeners) {
      if (listener.type === type) {
        try {
          listener.callback(...args);
        } catch (error) {
          console.error(`Error in audio listener for ${type}:`, error);
        }
      }
    }
  }

  update() {
    // Update audio sources
    const currentTime = this.audioContext ? this.audioContext.currentTime : Date.now() / 1000;

    // Remove finished sources (Web Audio API only)
    if (!this.useHtml5Audio) {
      this.activeSources = this.activeSources.filter(({ source, startTime }) => {
        return currentTime < startTime + (source.buffer ? source.buffer.duration : 0);
      });
    }
  }

  dispose() {
    // Clean up audio resources
    if (this.audioContext) {
      this.audioContext.close();
    }

    // Stop all sounds and music
    this.stopAllMusic();

    // Dispose HTML5 audio elements
    if (this.useHtml5Audio) {
      for (const audio of Object.values(this.html5Audio)) {
        audio.pause();
        audio.src = '';
      }
      for (const music of Object.values(this.html5Music)) {
        music.pause();
        music.src = '';
      }
    }
  }
}

