// Create particle system using external ParticleSystem
    this.createParticleSystem(type, position, options) {
      // Import ParticleSystem from external file
      const externalParticleSystem = new ParticleSystem(scene, camera);

      // Create appropriate particle effect based on type
      switch (type) {
        case 'explosion':
          return externalParticleSystem.createExplosion(position, options);
        case 'fire':
          return externalParticleSystem.createFire(position, options);
        case 'smoke':
          return externalParticleSystem.createSmoke(position, options);
        default:
          return null;
      }
    }

    // Dispose function to clean up external particle systems
    this.dispose() {
      // Clean up resources
      this.renderer.dispose();

      for (const model of this.models.values()) {
        if (model.geometry) model.geometry.dispose();
        if (model.material) {
          if (Array.isArray(model.material)) {
            for (const material of model.material) {
              material.dispose();
            }
          } else {
            model.material.dispose();
          }
        }
      }

      for (const texture of this.textures.values()) {
        texture.dispose();
      }

      // Clean up external particle systems
      if (typeof ParticleSystem !== 'undefined') {
        const externalParticleSystem = new ParticleSystem(this.scene, this.camera);
        externalParticleSystem.dispose();
      }
    }

